entries[1214572] = { ["name"] = "Automatischer Fußbombenspender", ["text"] = "Unbegrenzte Reichweite\nSofort\nCa. 1.5 Procs pro Minute\nBranns Zauber und Fähigkeiten haben die Chance, 10 Sek. lang 2 Fußbomben auf das Feld zu werfen.\n\nWenn Ihr gegen eine Fußbombe lauft, wird sie auf Euer Ziel geschleudert und fügt allen Gegnern in einem Radius von 6 Metern beträchtlichen Feuerschaden zu.\n(30s Abklingzeit)" }
