entries[1214688] = { ["name"] = "Feuerwerk", ["text"] = "300 Meter Reichweite\nSofort\nRiks Bühnenarbeiter werfen Pyrotechnik in den Hof, die Spielercharakteren innerhalb von 2.5 Metern um ein Einschlag 6708070 Feuerschaden zufügt.\n\nPyrotechnik verteilt brennende Funken, die Spielercharakteren innerhalb von 2.5 Metern um die Einschlagspunkte 6708070 Feuerschaden zufügen.\n\nPyrotechnik verleiht ' Aufregung ', wenn sie angegriffen wird." }
entries[1214689] = { ["name"] = "Elektrogeladene Waffen", ["text"] = "Unbegrenzte Reichweite\nSofort\nBranns Ausrüstung ist mit hochmoderner Technologie aufgerüstet.\n\nElektrogeladener Schild\nAuf Brann gewirkte effektive Heilung pulsiert als Naturschaden.\n\nElektrogeladene Pistole\nJeder Schuss setzt elektrischen Strom frei, der auf Gegner in der Nähe überspringt und ihr Angriffstempo verringert. Wenn Brann geheilt wird, lädt sich seine Pistole über das Maximum hinaus auf und verursacht mehr Schaden.\n\nElektrogeladene Schrotflinte\nBei jedem getroffenen Gegner besteht eine Chance, dass er zu Boden gestoßen wird. Wenn Brann geheilt wird, lädt sich seine Flinte über das Maximum hinaus auf und verursacht mehr Schaden." }
