entries[1214882] = { ["name"] = "Raketenausrüstung mit Biotreibstoff", ["text"] = "Unbegrenzte Reichweite\nSofort\nGruppenmitglieder werden mit Raketenausrüstung mit Biotreibstoff ausgerüstet.\n\nBiotreibstoff\nJeder getötete Gegner füllt die Raketenausrüstung mit Biotreibstoff auf und erhöht damit 10 Sek. lang die Bewegungsgeschwindigkeit um 2% und das Tempo um 2%. Bis zu 10-mal stapelbar." }
