entries[1214920] = { ["name"] = "Himmelsjäger von Nachtsturz", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen Himmelsjäger von Nachtsturz oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n\"Die Schreie dieser Himmelsjäger, die sich in der tiefsten Nacht aus dem Himmel auf ihre Beute stürzen, haben einst alle Kinder Draenors mit Furcht erfüllt.\"\nVerkäufer:\nKronnus\nZone:\nKriegsspeer\nKosten:\n5.000\n\nVerkäufer:\nTempra\nZone:\nSturmschild\nKosten:\n5.000" }
