entries[1214930] = { ["name"] = "Rückentwickelte Goblintodesbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn die Gesundheit eines Spielcharakters während eines Kampfes unter 50% fällt, wirft Brann eine riesige Bombe, die beim Einschlag explodiert.\n\nDie Explosion stößt umstehende Gegner zurück, verlangsamt sie 5 Sek. lang um 45% und heilt Gruppenmitglieder in der Nähe um 35% ihrer maximalen Gesundheit. Kann nur einmal alle 1.5 Min. auftreten." }
