entries[1214940] = { ["name"] = "Ur'zulfleischreißer", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen Ur'zulfleischreißer oder gibt ihn wieder frei.\n\"Dieser furchteinflößende Ur'zul nimmt seine Opfer in sich auf und schafft dadurch ein nahezu unaufhaltsames Monster. Zum Glück behandelt Ihr ihn gut, sonst könntet Ihr sein nächster Leckerbissen werden.\"\nVerkäufer:\nAridormi\nZone:\nDalaran\nKosten:\n5.000" }
