entries[1215609] = { ["name"] = "Mönchsklassenset, Nebelwirker, 11.1, 4 Teile", ["text"] = "Der Einsatz von 'Erneuernder Nebel' wendet für 6 Sek. Versicherung! an. Die Heilung von Versicherung! wird um bis zu 50% im Verhältnis zu der Abdeckung erhöht, die 'Erneuernder Nebel' auf Euch und bis zu 10 Verbündeten hat." }
