entries[1215611] = { ["name"] = "Schamanenklassenset, Wiederherstellung, 11.1, 4 Teile", ["text"] = "Wenn Ihr ' [ Wogendes Totem / Heilender Regen]' einsetzt, wird [ Wogendes Totem : 2 ] Verbündeten im Umkreis Versicherung! gewährt. Wenn Versicherung! verbraucht wird, heilt Euer nächster Einsatz von 'Kettenheilung', 'Heilende Woge' oder 'Welle der Heilung' [ Wogendes Totem : 10 / 10]% mehr Gesundheit." }
